import json
from fractions import Fraction

result = Fraction(144, 12)
if result.denominator == 1:
    print(json.dumps({
        "final_answer": str(result.numerator),
        "evidence": {"dividend": 144, "divisor": 12, "quotient": result.numerator}
    }, separators=(",", ":")))
else:
    print("UNSUPPORTED")
```

